#!/bin/bash
# Uninstall script for Dia
# Generated by IntuneBrew

# Exit on error
set -e

echo "Uninstalling Dia..."

# Check if running as root
if [ "$EUID" -ne 0 ]; then
  echo "Please run as root"
  exit 1
fi

# Kill application process if running
echo "Stopping Dia if running..."
pkill -f "Dia" 2>/dev/null || true

# Remove /Applications/Dia.app
echo "Removing /Applications/Dia.app..."
if [ -d "/Applications/Dia.app" ]; then
    rm -rf "/Applications/Dia.app" 2>/dev/null || true
elif [ -f "/Applications/Dia.app" ]; then
    rm -f "/Applications/Dia.app" 2>/dev/null || true
fi

# Remove $HOME/Library/Application Support/Dia
echo "Removing $HOME/Library/Application Support/Dia..."
if [ -d "$HOME/Library/Application Support/Dia" ]; then
    rm -rf "$HOME/Library/Application Support/Dia" 2>/dev/null || true
elif [ -f "$HOME/Library/Application Support/Dia" ]; then
    rm -f "$HOME/Library/Application Support/Dia" 2>/dev/null || true
fi

# Remove $HOME/Library/Caches/company.thebrowser.dia
echo "Removing $HOME/Library/Caches/company.thebrowser.dia..."
if [ -d "$HOME/Library/Caches/company.thebrowser.dia" ]; then
    rm -rf "$HOME/Library/Caches/company.thebrowser.dia" 2>/dev/null || true
elif [ -f "$HOME/Library/Caches/company.thebrowser.dia" ]; then
