# Remove $HOME/Library/HttpStorages/company.thebrowser.dia.binarycookies
echo "Removing $HOME/Library/HttpStorages/company.thebrowser.dia.binarycookies..."
if [ -d "$HOME/Library/HttpStorages/company.thebrowser.dia.binarycookies" ]; then
    rm -rf "$HOME/Library/HttpStorages/company.thebrowser.dia.binarycookies" 2>/dev/null || true
elif [ -f "$HOME/Library/HttpStorages/company.thebrowser.dia.binarycookies" ]; then
    rm -f "$HOME/Library/HttpStorages/company.thebrowser.dia.binarycookies" 2>/dev/null || true
fi

# Remove $HOME/Library/Preferences/company.thebrowser.dia.plist
echo "Removing $HOME/Library/Preferences/company.thebrowser.dia.plist..."
if [ -d "$HOME/Library/Preferences/company.thebrowser.dia.plist" ]; then
